create policy "participants read offer rounds" on public.offer_rounds
  as permissive
  for select
  to authenticated
  using (buyer_id = (( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM public.listings l
  WHERE l.id = offer_rounds.listing_id AND l.seller_id = (( SELECT auth.uid() AS uid)))) OR ( SELECT public.is_admin() AS is_admin));
